import React, { useState } from "react";

function ListAuthor() {
  const [authors, setAuthors] = useState([
    // Example demo data — you can replace with API later
    { id: 1, name: "George Orwell", country: "UK" },
    { id: 2, name: "Chinua Achebe", country: "Nigeria" },
  ]);

  const handleCreate = () => {
    alert("Open create form here");
  };

  const handleEdit = (id) => {
    alert("Edit author with ID: " + id);
  };

  const handleDelete = (id) => {
    if (window.confirm("Are you sure you want to delete this author?")) {
      setAuthors(authors.filter((a) => a.id !== id));
    }
  };

  return (
    <div className="content-wrapper">
      {/* Page Header */}
      <section className="content-header">
        <div className="container-fluid d-flex justify-content-between align-items-center">
          <h1>List of Authors</h1>

          {/* Create Button */}
          <button
            onClick={handleCreate}
            className="btn btn-primary"
          >
            <i className="fas fa-plus"></i> Add New Author
          </button>
        </div>
      </section>

      {/* Main Content */}
      <section className="content">
        <div className="card">
          <div className="card-header">
            <h3 className="card-title">Author List</h3>
          </div>

          <div className="card-body">
            <table className="table table-bordered table-hover">
              <thead>
                <tr>
                  <th style={{ width: "50px" }}>#</th>
                  <th>Name</th>
                  <th>Country</th>
                  <th style={{ width: "150px" }}>Actions</th>
                </tr>
              </thead>

              <tbody>
                {authors.length > 0 ? (
                  authors.map((author, index) => (
                    <tr key={author.id}>
                      <td>{index + 1}</td>
                      <td>{author.name}</td>
                      <td>{author.country}</td>
                      <td>
                        <button
                          onClick={() => handleEdit(author.id)}
                          className="btn btn-sm btn-info mr-2"
                        >
                          <i className="fas fa-edit"></i>
                        </button>

                        <button
                          onClick={() => handleDelete(author.id)}
                          className="btn btn-sm btn-danger"
                        >
                          <i className="fas fa-trash"></i>
                        </button>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="4" className="text-center text-muted">
                      No authors found.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>

        </div>
      </section>
    </div>
  );
}

export default ListAuthor;
